<?php
declare(strict_types=1);if(!defined('REDFOX_SKIP_BOTAPI_ROUTER'))define('REDFOX_SKIP_BOTAPI_ROUTER',true);require_once __DIR__.'/../lib/Security.php';redfox_secure_session_start();require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/icons.php';$q=$pdo->prepare('SELECT * FROM admin WHERE username=? LIMIT 1');$q->execute([$_SESSION['user']??'']);$admin=$q->fetch(PDO::FETCH_ASSOC);if(!$admin){header('Location:login.php');exit;}$main=($admin['rule']??'')==='administrator';try{rx_require_schema($pdo,['app','content_categories'],['app'=>['platform','enabled']]);}catch(Throwable$e){header('Location:migrations.php?required=apps_categories');exit;}$flash='';$ft='success';
$slug=function($s){$x=strtolower(preg_replace('/[^A-Za-z0-9]+/','-',trim((string)$s)));return trim($x,'-')?:'cat-'.bin2hex(random_bytes(3));};
if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&$main){try{$a=(string)($_POST['action']??'');if($a==='cat_add'){$name=mb_substr(trim((string)$_POST['name']),0,191);if($name==='')throw new RuntimeException('نام دسته لازم است.');$pdo->prepare("INSERT INTO content_categories(section,name,slug,enabled,sort_order,created_at) VALUES('app',?,?,1,?,?)")->execute([$name,$slug($_POST['slug']??$name),(int)($_POST['sort_order']??0),time()]);$flash='دسته نرم‌افزار ساخته شد.';}elseif($a==='cat_edit'){$id=(int)$_POST['id'];$name=mb_substr(trim((string)$_POST['name']),0,191);$pdo->beginTransaction();$old=$pdo->prepare("SELECT name FROM content_categories WHERE id=? AND section='app' FOR UPDATE");$old->execute([$id]);$oldName=(string)$old->fetchColumn();if($oldName==='')throw new RuntimeException('دسته پیدا نشد.');$pdo->prepare("UPDATE content_categories SET name=?,enabled=?,sort_order=? WHERE id=? AND section='app'")->execute([$name,isset($_POST['enabled'])?1:0,(int)($_POST['sort_order']??0),$id]);$pdo->prepare('UPDATE app SET platform=? WHERE platform=?')->execute([$name,$oldName]);$pdo->commit();$flash='دسته و نرم‌افزارهای آن بروزرسانی شدند.';}elseif($a==='cat_delete'){$id=(int)$_POST['id'];$q=$pdo->prepare("SELECT name FROM content_categories WHERE id=? AND section='app'");$q->execute([$id]);$name=(string)$q->fetchColumn();$c=$pdo->prepare('SELECT COUNT(*) FROM app WHERE platform=?');$c->execute([$name]);if((int)$c->fetchColumn()>0)throw new RuntimeException('ابتدا نرم‌افزارهای این دسته را منتقل یا حذف کنید.');$pdo->prepare("DELETE FROM content_categories WHERE id=? AND section='app'")->execute([$id]);$flash='دسته حذف شد.';}elseif($a==='add'||$a==='edit'){$id=(int)($_POST['id']??0);$name=mb_substr(trim((string)$_POST['name']),0,191);$link=trim((string)$_POST['link']);$platform=trim((string)$_POST['platform']);if($name===''||!filter_var($link,FILTER_VALIDATE_URL))throw new RuntimeException('نام یا لینک معتبر نیست.');$v=$pdo->prepare("SELECT COUNT(*) FROM content_categories WHERE section='app' AND name=?");$v->execute([$platform]);if((int)$v->fetchColumn()!==1)throw new RuntimeException('دسته سیستم‌عامل نامعتبر است.');if($a==='add')$pdo->prepare('INSERT INTO app(name,link,platform,enabled) VALUES(?,?,?,1)')->execute([$name,$link,$platform]);else$pdo->prepare('UPDATE app SET name=?,link=?,platform=? WHERE id=?')->execute([$name,$link,$platform,$id]);$flash='نرم‌افزار ذخیره شد.';}elseif($a==='toggle'){$pdo->prepare('UPDATE app SET enabled=1-enabled WHERE id=?')->execute([(int)$_POST['id']]);$flash='وضعیت تغییر کرد.';}elseif($a==='delete'){$pdo->prepare('DELETE FROM app WHERE id=?')->execute([(int)$_POST['id']]);$flash='نرم‌افزار حذف شد.';}}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$flash=redfox_public_exception($e, 'panel/apps.php');$ft='error';}}
$cats=$pdo->query("SELECT * FROM content_categories WHERE section='app' AND id IN(SELECT MIN(id) FROM content_categories WHERE section='app' GROUP BY LOWER(TRIM(name))) ORDER BY sort_order,id")->fetchAll(PDO::FETCH_ASSOC);$apps=$pdo->query('SELECT * FROM app ORDER BY platform,name')->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>نرم‌افزارها</title><link rel="stylesheet" href="css/theme.css"><style>.rx-content-manager .card{background:linear-gradient(145deg,var(--surface-1),var(--surface-2));border:1px solid var(--border-soft);box-shadow:0 8px 22px rgba(0,0,0,.12);padding:14px!important}.rx-content-manager form{display:flex;gap:6px;flex-wrap:wrap;align-items:center}.rx-content-manager input,.rx-content-manager select{border:1px solid var(--border-mid);border-radius:9px;background:var(--surface-1);color:var(--text-main);padding:6px 8px;font-size:12px;font-family:inherit}.rx-content-manager .app-table tr:hover{background:var(--accent-soft)}@media(max-width:700px){.rx-content-manager form>*{width:100%!important}}.rx-content-manager .btn{border-radius:8px;padding:6px 10px!important;font-size:11px!important;min-height:30px!important}.rx-content-manager .app-table td{padding:7px 6px!important}</style></head><body class="rx-content-manager"><section id="container"><?php include'header.php';?><section id="main-content"><div class="wrapper"><div class="page-head"><h1 class="page-head__title">نرم‌افزارهای اتصال</h1><div class="page-head__sub">دسته‌بندی بر اساس سیستم‌عامل؛ فقط موارد فعال در ربات نمایش داده می‌شوند.</div></div><?php if($flash):?><div class="card <?=$ft?>"><?=htmlspecialchars($flash)?></div><?php endif;?>
<div class="card"><h2>دسته‌بندی سیستم‌عامل</h2><div class="page-guide">دسته‌ها را ایجاد، مرتب یا غیرفعال کنید. دسته غیرفعال در ربات نمایش داده نمی‌شود.</div><form method="post"><input type="hidden" name="action" value="cat_add"><input name="name" placeholder="مثلاً اندروید" required><input name="slug" placeholder="android"><input type="number" name="sort_order" value="0"><button class="btn btn-success">ایجاد دسته</button></form><div class="table-wrap"><table class="app-table"><tr><th>نام</th><th>شناسه</th><th>ترتیب</th><th>وضعیت و مدیریت</th></tr><?php foreach($cats as$c):$fid='cat-form-'.$c['id'];?><tr><td><input form="<?=$fid?>" name="name" value="<?=htmlspecialchars($c['name'])?>"></td><td><code><?=htmlspecialchars($c['slug'])?></code></td><td><input form="<?=$fid?>" type="number" name="sort_order" value="<?=$c['sort_order']?>" style="width:70px"></td><td><form id="<?=$fid?>" method="post"><input type="hidden" name="action" value="cat_edit"><input type="hidden" name="id" value="<?=$c['id']?>"><label><input type="checkbox" name="enabled" <?=$c['enabled']?'checked':''?>> فعال</label><button class="btn btn-primary">ذخیره تغییرات</button></form><form method="post" onsubmit="return confirm('دسته حذف شود؟')"><input type="hidden" name="action" value="cat_delete"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn btn-danger">حذف</button></form></td></tr><?php endforeach;?></table></div></div>
<div class="card"><h2>افزودن نرم‌افزار</h2><form method="post"><input type="hidden" name="action" value="add"><input name="name" placeholder="نام نرم‌افزار" required><input type="url" name="link" placeholder="لینک رسمی" required><select name="platform" required><option value="">انتخاب سیستم‌عامل</option><?php foreach($cats as$c):?><option <?=!$c['enabled']?'disabled':''?>><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><button class="btn btn-success">افزودن</button></form></div>
<div class="card"><h2>فهرست نرم‌افزارها</h2><div class="table-wrap"><table class="app-table"><tr><th>نام</th><th>سیستم‌عامل</th><th>لینک</th><th>وضعیت و مدیریت</th></tr><?php foreach($apps as$x):$fid='app-form-'.$x['id'];?><tr><td><input form="<?=$fid?>" name="name" value="<?=htmlspecialchars($x['name'])?>"></td><td><select form="<?=$fid?>" name="platform"><?php foreach($cats as$c):?><option <?=$x['platform']===$c['name']?'selected':''?>><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select></td><td><input form="<?=$fid?>" type="url" name="link" value="<?=htmlspecialchars($x['link'])?>" style="width:300px"></td><td><span class="badge"><?=$x['enabled']?'فعال':'غیرفعال'?></span><form id="<?=$fid?>" method="post"><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn btn-primary">ذخیره ویرایش</button></form><form method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn">تغییر وضعیت</button></form><form method="post" onsubmit="return confirm('حذف شود؟')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn btn-danger">حذف</button></form></td></tr><?php endforeach;?></table></div></div></div></section></section></body></html>
